// The orders service decides WHEN a notice goes out. This node decides WHAT it says.
// Edit the wording here; the service never needs to change.
const n = $json.body ?? {};
const hi = n.first_name ? 'Hi ' + n.first_name + ',' : 'Hi,';
const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const sign = '<p>Thanks,<br>' + esc(n.store || 'Loblolly') + '</p>';

if (n.kind === 'shipped') {
  const track = n.tracking_url
    ? '<p>Tracking: <a href="' + esc(n.tracking_url) + '">' + esc(n.tracking_company || 'Track package') + ' ' + esc(n.tracking_number || '') + '</a></p>'
    : (n.tracking_number ? '<p>Tracking number: ' + esc(n.tracking_company || '') + ' ' + esc(n.tracking_number) + '</p>' : '');
  return { json: { channel: 'email', notice_id: n.id, to: n.to_email, sender: n.store,
    subject: 'Your ' + n.store + ' order ' + n.order_number + ' has shipped',
    html: '<p>' + esc(hi) + '</p><p>Good news: order ' + esc(n.order_number) + ' is on its way.</p>' + track + sign } };
}
if (n.kind === 'delayed') {
  return { json: { channel: 'email', notice_id: n.id, to: n.to_email, sender: n.store,
    subject: 'An update on your ' + n.store + ' order ' + n.order_number,
    html: '<p>' + esc(hi) + '</p><p>Order ' + esc(n.order_number) + ' is taking longer than usual to leave our shop. ' +
      'Nothing is needed from you. We are on it and will email tracking as soon as it ships.</p>' +
      '<p>If you have a question in the meantime, just reply to this email.</p>' + sign } };
}
if (n.kind === 'stuck_alert') {
  return { json: { channel: 'slack', notice_id: n.id,
    text: ':warning: *Paid order not shipped* ' + n.store + ' ' + n.order_number + ' ($' + n.total + ')\n' +
      'Paid ' + n.paid_at + ', no fulfillment after ' + n.threshold_hours + ' h. The customer was sent a delay notice.' } };
}
if (n.kind === 'unmatched_refund') {
  return { json: { channel: 'slack', notice_id: n.id,
    text: ':mag: *Stripe refund with no matching wholesale order*\nCharge ' + n.charge + ', payment intent ' + (n.payment_intent || 'none') +
      ', refunded $' + n.amount_refunded + '. Check it in Stripe.' } };
}
return { json: { channel: 'slack', notice_id: n.id, text: ':grey_question: Orders service sent an unknown notice kind: ' + JSON.stringify(n).slice(0, 500) } };
